<?php
if (session_status() === PHP_SESSION_NONE) { session_start(); }include_once("../../config/koneksi.php");
if(!isset($_SESSION['user_id'])){header('Location: ../../login.php');exit();}if(strtolower($_SESSION['role']??'')!=='owner'){header('Location: user_dashboard.php');exit();}
function owner_data($kon){$user_id=(int)($_SESSION['user_id']??0);if(!$user_id)return null;$stmt=mysqli_prepare($kon,"SELECT * FROM tb_pemilik_mobil WHERE id_user=? LIMIT 1");if(!$stmt)return null;mysqli_stmt_bind_param($stmt,'i',$user_id);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$data=$res?mysqli_fetch_assoc($res):null;mysqli_stmt_close($stmt);return $data;}
function owner_escape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function owner_rp($v){return 'Rp '.number_format((float)$v,0,',','.');}
$owner=owner_data($kon);$owner_id=(int)($owner['id_pemilik']??0);$id=(int)($_GET['id']??0);$rental=null;
if($owner_id&&$id){$stmt=mysqli_prepare($kon,"SELECT r.*,p.nama nama_pelanggan,p.email email_pelanggan,p.no_hp no_hp_pelanggan,m.merk,m.tipe,m.plat_mobil,m.harga_rental FROM tb_rental r LEFT JOIN tb_pelanggan p ON p.id_pelanggan=r.id_pelanggan INNER JOIN tb_mobil m ON m.plat_mobil=r.plat_mobil WHERE r.id_rental=? AND m.id_pemilik=? LIMIT 1");if($stmt){mysqli_stmt_bind_param($stmt,'ii',$id,$owner_id);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$rental=$res?mysqli_fetch_assoc($res):null;mysqli_stmt_close($stmt);}}
$owner_page='transaksi';$owner_title='Detail Rental';include 'owner_header.php';
?>
<div class="page-head"><div><h1>Detail Rental</h1><p>Informasi transaksi dari armada milik Anda.</p></div><a class="btn secondary" href="owner_transaksi.php">← Kembali ke Riwayat Rental</a></div>
<div class="section"><?php if(!$rental): ?><div class="notice">Data rental tidak ditemukan atau bukan transaksi dari armada Anda.</div><?php else:$awal=new DateTime($rental['waktu_pinjam']);$akhir=new DateTime($rental['waktu_kembali']);$jam=($akhir->getTimestamp()-$awal->getTimestamp())/3600;$hari=(int)ceil($jam/24); ?><div class="table-wrap"><table border="1" cellpadding="8" cellspacing="0" width="100%"><tr><th>ID Rental</th><td>#<?php echo owner_escape($rental['id_rental']); ?></td></tr><tr><th>Status</th><td><?php echo owner_escape($rental['status_rental']); ?></td></tr><tr><th>Penyewa</th><td><?php echo owner_escape($rental['nama_pelanggan']??'-'); ?></td></tr><tr><th>Email</th><td><?php echo owner_escape($rental['email_pelanggan']??'-'); ?></td></tr><tr><th>No HP</th><td><?php echo owner_escape($rental['no_hp_pelanggan']??'-'); ?></td></tr><tr><th>Kendaraan</th><td><?php echo owner_escape($rental['merk'].' '.$rental['tipe']); ?> - <?php echo owner_escape($rental['plat_mobil']); ?></td></tr><tr><th>Waktu Pinjam</th><td><?php echo owner_escape($rental['waktu_pinjam']); ?></td></tr><tr><th>Waktu Kembali</th><td><?php echo owner_escape($rental['waktu_kembali']); ?></td></tr><tr><th>Durasi</th><td><?php echo $hari; ?> hari</td></tr><tr><th>Tarif Sewa</th><td><?php echo owner_rp($rental['harga_rental']); ?> / hari</td></tr><tr><th>Omset Transaksi</th><td><strong><?php echo owner_rp($rental['total_harga']); ?></strong></td></tr></table></div><?php endif; ?></div>
<?php include 'owner_footer.php'; ?>
